import React from 'react';
import { Link } from 'react-router-dom';
import { FiCpu, FiLink2 } from 'react-icons/fi';
import Seo from '../components/Seo';
import { ArtBand } from '../components/Art';
import { withFunnelParams } from '../utils/funnel';

// Home: one workspace, and what you add to it. Hero (illustration) -> the workspace Projects card drawn in HTML
// -> the two cloud tools with a piece of their interface -> the two hardware products -> research -> closing.
// Hardware appears as text only; the photographs belong to the Nexus and Bridge pages.
const projects = [
  ['ECU bench', true, true],
  ['Brake rig', true, false],
];
const coming = ['Nexus', 'Bridge', 'GPU compute', 'Other sources'];
const requirements = [
  ['REQ-012', 'Brake pressure reaches 40 bar within 200 ms', 'Approved'],
  ['REQ-013', 'Pressure drops to zero when the pedal is released', 'In review'],
  ['REQ-014', 'A fault is logged when the sensor signal is lost', 'Draft'],
];
const events = [
  ['12:00:04', 'test.completed', 'passed', true],
  ['12:00:01', 'motor.sample', '72.4 °C'],
  ['11:59:58', 'motor.sample', '71.9 °C'],
];
const research = [
  ['/research/reports', 'Technical reports', 'Studies on agentic test and validation workflows'],
  ['/research', 'Model results', 'Comparisons and benchmark data'],
  ['/research/methodology', 'Methodology', 'How the evaluations are run'],
];

const Switch = ({ on }) => <i className={`lh-sw${on ? ' is-on' : ''}`} />;

export default function Home() {
  return <main className="home-design lx-home lh">
    <Seo title="Plotune: one workspace for engineering work" description="Create a Plotune workspace, add projects, and switch on what each project needs: RMS for requirements and test evidence, Stream for event history. Nexus and Bridge hardware connect to the same work." path="/" />
    <div className="design-container">
      <ArtBand as="header" hero priority name="cloud-platform" className="lh-hero">
        <h1>One workspace for engineering work.<br />Add what each project needs.</h1>
        <p>Create a workspace, add projects, and switch on the tools each one uses. <span className="m-hide">Hardware and compute are coming next.</span></p>
        <div className="lx-actions">
          <Link className="design-button" to="/register">Create a workspace</Link>
          <a className="design-button secondary" href="#workspace">See how it works</a>
        </div>
      </ArtBand>

      <section className="lx-section" id="workspace" aria-labelledby="lh-add">
        <div className="lx-head"><h2 id="lh-add">How it works</h2></div>
        <div className="lh-how">
        <div className="lh-ws">
          <div className="lh-ws-head"><h3>Projects <small>2</small></h3><span aria-hidden="true">New project</span></div>
          <ul className="lh-ws-list" aria-label="Example projects and the tools switched on in each">
            {projects.map(([name, rms, stream]) => <li key={name} className="lh-ws-row">
              <span className="lh-ws-name" translate="no">{name}</span>
              <span className="lh-svc-group">
                <span className={`lh-svc${rms ? ' is-on' : ''}`}><span translate="no">RMS</span><Switch on={rms} /><span className="sr-only">{rms ? 'on' : 'off'}</span></span>
                <span className={`lh-svc${stream ? ' is-on' : ''}`}><span translate="no">Stream</span><Switch on={stream} /><span className="sr-only">{stream ? 'on' : 'off'}</span></span>
              </span>
            </li>)}
          </ul>
          <ul className="lh-coming" aria-label="Coming to the workspace">
            {coming.map((name) => <li key={name}><span translate="no">{name}</span><em>Coming</em></li>)}
          </ul>
        </div>
        <ol className="lh-steps">
          <li><b>Create a workspace</b><span>Invite the people you work with and give each a role.</span></li>
          <li><b>Add a project</b><span>One project per product, bench or programme.</span></li>
          <li><b>Switch on its tools</b><span>RMS and Stream today. Nexus, Bridge, GPU compute and other sources are next.</span></li>
        </ol>
        </div>
      </section>

      <section className="lx-section" aria-labelledby="lh-cloud">
        <ArtBand as="div" name="shape-network" className="lh-band">
          <h2 id="lh-cloud">In the cloud</h2>
          <p>Available today, switched on per project.</p>
        </ArtBand>
        <div className="lh-duo">
          <article className="lx-card lh-tool">
            <h3 translate="no">RMS</h3>
            <p>Requirements with review, traceability links, test cases and recorded evidence.</p>
            <div className="lh-peek" aria-hidden="true">
              {requirements.map(([id, text, state]) => <div key={id} className="lh-peek-row">
                <code>{id}</code><span>{text}</span><b className={`lh-chip lh-chip-${state.toLowerCase().replace(' ', '-')}`}>{state}</b>
              </div>)}
            </div>
            <Link className="lx-more" to="/rms">Explore <span translate="no">RMS</span></Link>
          </article>
          <article className="lx-card lh-tool">
            <h3 translate="no">Stream</h3>
            <p>One explorable event history from your tools, test benches and scripts.</p>
            <div className="lh-peek" aria-hidden="true">
              {events.map(([t, ev, val, ok]) => <div key={t} className="lh-peek-row">
                <code>{t}</code><span>{ok && <i className="lx-ok" />}{ev}</span><b className="lx-kv">{val}</b>
              </div>)}
            </div>
            <Link className="lx-more" to="/stream"><span>Explore </span><span translate="no">Stream</span></Link>
          </article>
        </div>
      </section>

      <section className="lx-section" aria-labelledby="lh-bench">
        <ArtBand as="div" name="mechanical-testing" className="lh-band">
          <h2 id="lh-bench">On the bench</h2>
          <p>Hardware products that work on their own today.</p>
        </ArtBand>
        <div className="lh-duo">
          <article className="lx-card lh-tool">
            <span className="lx-glyph"><FiCpu aria-hidden="true" /></span>
            <h3 translate="no">Nexus</h3>
            <p>Connects AI agents to physical engineering and test systems through MCP.</p>
            <Link className="lx-more" to={withFunnelParams('/nexus')}>Explore <span translate="no">Nexus</span></Link>
          </article>
          <article className="lx-card lh-tool">
            <span className="lx-glyph"><FiLink2 aria-hidden="true" /></span>
            <h3 translate="no">Bridge</h3>
            <p>CAN, Serial, DAQ and I/O. Wireless, managed from the browser.</p>
            <Link className="lx-more" to={withFunnelParams('/bridge')}>Explore <span translate="no">Bridge</span></Link>
          </article>
        </div>
      </section>

      <section className="lx-section" aria-labelledby="lh-research">
        <div className="lx-head"><h2 id="lh-research">Engineering needs evidence.</h2><p className="lx-sub">Technical studies, benchmark data and the methods behind agentic test and validation.</p></div>
        <div className="lx-list">{research.map(([to, title, copy]) => <Link key={to} to={to}><b>{title}</b><span>{copy}</span><i aria-hidden="true">→</i></Link>)}</div>
      </section>

      <ArtBand name="rocket-launch" className="lh-closing">
        <h2>Not sure where to start?</h2>
        <p>Tell us what you work on and we will point you to the right place to begin.</p>
        <div className="lx-actions"><Link className="design-button" to={withFunnelParams('/contact')}>Talk to us</Link><Link className="design-button secondary" to="/docs">Read the docs</Link></div>
      </ArtBand>
      <div className="lx-bottom" />
    </div>
  </main>;
}
