import React from 'react';
import { ArtBand } from './Art';
import '../public-pages.css';

// Shared hero for the company, resource and account pages: h1, one muted lead, actions, and (optionally) one
// illustration as the hero's background (text over its empty left side; below the text on a phone). No eyebrow label above the heading.
export default function PageHero({ title, lead, art, artAlt = '', children, className = '', as: Tag = 'section' }) {
  if (art) {
    return (
      <ArtBand as={Tag} hero priority name={art} alt={artAlt} className={`design-container pg-hero has-art ${className}`.trim()}>
        <h1>{title}</h1>
        {lead && <p className="pg-lead">{lead}</p>}
        {children}
      </ArtBand>
    );
  }
  return (
    <Tag className={`design-container pg-hero ${className}`.trim()}>
      <div className="pg-hero-text">
        <h1>{title}</h1>
        {lead && <p className="pg-lead">{lead}</p>}
        {children}
      </div>
    </Tag>
  );
}
