import React from 'react';
import meta from '../content/art.json';

// The brand illustrations in public/assets/art (names are the keys of src/content/art.json; rebuilt by scripts/build-art.py).
// The drawings are wide (about 1913 x 822) with the subject on the right and the left 65% empty, and their ground is
// transparent, so they sit straight on the page or on a card: no panel, no border around them.
const BASE = '/assets/art/';
const cropSet = (name) => `${BASE}${name}-crop-560.webp 560w, ${BASE}${name}-crop-960.webp 960w`;
const wideSet = (name) => `${BASE}${name}-1200.webp 1200w, ${BASE}${name}-1913.webp 1913w`;
const loading = (priority) => (priority ? { fetchpriority: 'high', decoding: 'async' } : { loading: 'lazy', decoding: 'async' });

// The drawing alone, cropped to its subject. For cards and small spots.
export default function Art({ name, alt = '', priority = false, sizes, className = '' }) {
  const m = meta[name];
  if (!m) return null;
  return <img className={`art ${className}`.trim()} src={`${BASE}${name}-crop-960.webp`} srcSet={cropSet(name)} sizes={sizes || '(max-width: 860px) 100vw, 560px'} width={m.cw} height={m.ch} alt={alt} {...loading(priority)} />;
}

// A section with the drawing as its background: the text sits over the empty left side and the subject fills the right.
// Below 860 px the text comes first and the drawing follows it edge to edge. Use it for a page hero (`hero`) and for
// sections further down. `as` sets the element (section by default).
export function ArtBand({ name, alt = '', priority = false, hero = false, className = '', as: Tag = 'section', children, ...rest }) {
  const m = meta[name];
  // Where the subject sits in the wide canvas, as ratios of the subject's width: the CSS sizes the drawing so that the
  // subject always takes the same share of the band, whatever the drawing, and the text never runs into it.
  const style = m ? { '--art-scale': (m.w / m.cw).toFixed(4), '--art-right': ((m.w - m.cx - m.cw) / m.cw).toFixed(4), '--art-bottom': ((m.h - m.cy - m.ch) / m.cw).toFixed(4), '--art-ratio': (m.ch / m.cw).toFixed(4) } : undefined;
  return (
    <Tag className={`art-band${hero ? ' art-band--hero' : ''} ${className}`.trim()} style={style} {...rest}>
      <div className="art-band-text">{children}</div>
      {m && (
        <picture className="art-band-art" aria-hidden={alt ? undefined : 'true'}>
          <source media="(max-width: 860px)" srcSet={cropSet(name)} sizes="100vw" />
          <img src={`${BASE}${name}-1200.webp`} srcSet={wideSet(name)} sizes="(max-width: 1400px) 1200px, 1913px" width={m.w} height={m.h} alt={alt} {...loading(priority)} />
        </picture>
      )}
    </Tag>
  );
}
