import React, { useState, useContext, useEffect } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { FiMenu, FiLogOut, FiChevronDown, FiUsers } from 'react-icons/fi';
import logo from '../assets/logo.png';
import { AuthContext } from '../context/AuthContext';

// SVG icons instead of the Material Icons ligature font: that font is an external Google Fonts
// load, and when it fails (slow network, ad blocker, offline) the ligature falls back to its
// literal name as visible text (e.g. a login link showing "account_circle").
const navIconMap = { workspaces: FiUsers };
const NavIcon = ({ name, className }) => {
  const Icon = navIconMap[name];
  return Icon ? <Icon className={className} /> : null;
};

const Header = () => {
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [openDropdown, setOpenDropdown] = useState(null);
  const { user, logout } = useContext(AuthContext);
  const isLoggedIn = !!user;
  const location = useLocation();

  // Lokasyon değiştiğinde mobile menüyü kapat
  useEffect(() => {
    setIsMobileMenuOpen(false);
    setOpenDropdown(null);
  }, [location]);

  // Doherty/Occam: Escape and outside clicks close the open dropdown, instead of
  // requiring a precise second click on the same chevron.
  useEffect(() => {
    if (!openDropdown && !isMobileMenuOpen) return undefined;
    const onKeyDown = (event) => {
      if (event.key === 'Escape') { setOpenDropdown(null); setIsMobileMenuOpen(false); }
    };
    const onMouseDown = (event) => {
      if (event.target instanceof Element && !event.target.closest('[data-nav-dropdown]')) {
        setOpenDropdown(null);
      }
    };
    document.addEventListener('keydown', onKeyDown);
    document.addEventListener('mousedown', onMouseDown);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      document.removeEventListener('mousedown', onMouseDown);
    };
  }, [openDropdown, isMobileMenuOpen]);

  const toggleMobileMenu = () => {
    setIsMobileMenuOpen((current) => !current);
    setOpenDropdown(null);
  };

  const toggleDropdown = (itemPath) => {
    setOpenDropdown((current) => current === itemPath ? null : itemPath);
  };

  const handleLogout = () => {
    logout();
    setOpenDropdown(null);
  };

  // Navigation: Cloud (tools added to a workspace) and Hardware (products of their own), then the rest.
  // A menu's children are links; `sub: true` marks a child that belongs to the link above it.
  const guestNavItems = [
    { label: 'Cloud', children: [
      { to: '/rms', label: 'RMS', keepBrandName: true },
      { to: '/stream', label: 'Stream', keepBrandName: true },
    ] },
    { label: 'Hardware', children: [
      { to: '/nexus', label: 'Nexus', keepBrandName: true },
      { to: '/nexus/connectivity', label: 'Connectivity', sub: true },
      { to: '/nexus/stream', label: 'Stream integration', sub: true },
      { to: '/nexus/use-cases', label: 'Use Cases', sub: true },
      { to: '/ai-readiness', label: 'AI Readiness', sub: true },
      { to: '/bridge', label: 'Bridge', keepBrandName: true },
      { to: '/bridge/can', label: 'Bridge CAN', sub: true },
      { to: '/bridge/serial', label: 'Bridge Serial', sub: true },
      { to: '/bridge/daq', label: 'Bridge DAQ', sub: true },
      { to: '/bridge/io', label: 'Bridge I/O', sub: true },
      { to: 'https://bridge.plotune.net', label: 'Bridge workspace', isExternal: true, sub: true },
    ] },
    { to: '/research', label: 'Research', keepBrandName: true },
    { label: 'Docs', children: [
      { to: '/docs', label: 'Documentation' },
      { to: '/docs/nexus', label: 'Nexus Documentation' },
      { to: '/download', label: 'Desktop downloads' },
      { to: '/extensions', label: 'Extensions' },
      { to: '/faq', label: 'FAQ' },
    ] },
    { label: 'Company', children: [
      { to: '/about', label: 'About Plotune' },
      { to: '/careers', label: 'Careers' },
      { to: '/partners', label: 'Partnerships' },
      { to: '/contact', label: 'Contact' },
    ] },
  ];

  // Signed in, the marketing header keeps the public items and adds one way into the console.
  // Dashboard, Profile, Stream workspace and RMS are reached from the console's account menu.
  const navItems = isLoggedIn ? [...guestNavItems, { to: '/workspaces', label: 'Open console', icon: 'workspaces' }] : guestNavItems;

  const renderNavLink = (item) => {
    const isActive = item.children
      ? item.children.some((child) => location.pathname === child.to)
      : location.pathname === item.to;
    const linkClass = `site-nav-link flex min-h-[44px] items-center gap-2 rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary ${isActive ? 'is-active' : ''}`;

    if (item.children) {
      const dropdownId = `${item.label.toLowerCase().replace(/\s+/g, '-')}-submenu`;
      const isOpen = openDropdown === item.label;

      return (
        <div className="relative" data-nav-dropdown>
          <button
            type="button"
            className={`${linkClass} cursor-pointer`}
            aria-controls={dropdownId}
            aria-expanded={isOpen}
            onClick={() => toggleDropdown(item.label)}
          >
            {item.label}
            <FiChevronDown aria-hidden="true" className={`transition-transform ${isOpen ? 'rotate-180' : ''}`} />
          </button>
          <div id={dropdownId} className={`${isOpen ? 'block' : 'hidden'} xl:absolute xl:left-0 xl:top-full xl:mt-1 xl:min-w-56`}>
            <div className="site-menu">
              {item.children.map((child) => {
                const childClass = `site-menu-link flex min-h-[44px] items-center rounded-lg px-3 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary ${child.sub ? 'is-sub' : ''} ${
                  location.pathname === child.to ? 'is-active' : ''
                }`;
                const label = child.keepBrandName ? <span translate="no">{child.label}</span> : child.label;
                if (child.isExternal) {
                  return (
                    <a
                      key={child.to}
                      href={child.to}
                      target="_blank"
                      rel="noopener noreferrer"
                      className={`${childClass} whitespace-nowrap`}
                      onClick={() => setIsMobileMenuOpen(false)}
                    >
                      {label}
                      <span aria-hidden="true" className="ml-2 text-xs">↗</span>
                      <span className="sr-only">(opens in a new tab)</span>
                    </a>
                  );
                }
                return (
                  <Link
                    key={child.to}
                    to={child.to}
                    aria-current={location.pathname === child.to ? 'page' : undefined}
                    className={childClass}
                  >
                    {label}
                  </Link>
                );
              })}
            </div>
          </div>
        </div>
      );
    }

    return (
      <Link
        to={item.to}
        aria-current={isActive ? 'page' : undefined}
        className={linkClass}
      >
        {item.icon && <NavIcon name={item.icon} className="text-lg" />}
        {item.keepBrandName ? <span translate="no">{item.label}</span> : item.label}
      </Link>
    );
  };

  return (
    <header className="site-header fixed w-full top-0 z-50">
      <div className="site-header-in">
        <Link to="/" className="site-brand rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary">
          <img src={logo} alt="Plotune Logo" className="h-6 w-auto" />
          <span className="site-wordmark" translate="no">Plotune</span>
        </Link>
        <nav className="flex items-center" aria-label="Main navigation">
          <ul id="main-navigation" className={`xl:flex gap-1 ${isMobileMenuOpen ? 'flex flex-col absolute top-[52px] left-0 w-full bg-white p-5' : 'hidden xl:flex'}`}>
            {navItems.map((item) => (
              <li key={item.label}>
                {renderNavLink(item)}
              </li>
            ))}
            {/* Account actions in the phone menu */}
            {isLoggedIn && isMobileMenuOpen && (
              <li>
                <button
                  onClick={handleLogout}
                  aria-label="Log out"
                  className="site-nav-link flex min-h-[44px] min-w-[44px] items-center gap-2 text-left"
                >
                  <FiLogOut className="text-lg" />
                  <span>Log out</span>
                </button>
              </li>
            )}
            {!isLoggedIn && isMobileMenuOpen && (
              <>
                <li>
                  <Link to="/login" className="site-nav-link flex min-h-[44px] items-center rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary">
                    Log in
                  </Link>
                </li>
                <li>
                  <Link to="/register" className="design-button w-full">
                    Create a workspace
                  </Link>
                </li>
              </>
            )}
          </ul>

          {/* Desktop view - account actions */}
          <div className="hidden xl:flex items-center gap-3 ml-6">
            {isLoggedIn ? (
              <button
                onClick={handleLogout}
                aria-label="Log out"
                className="site-nav-link flex min-h-[44px] min-w-[44px] items-center justify-center rounded-lg focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
              >
                <FiLogOut className="text-lg" />
              </button>
            ) : (
              <>
                <Link to="/login" className="site-nav-link flex min-h-[44px] items-center rounded-lg px-2 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary">
                  Log in
                </Link>
                <Link to="/register" className="design-button site-cta">
                  Create a workspace
                </Link>
              </>
            )}
          </div>

          {/* Mobile menu button */}
          <button
            className="xl:hidden ml-2 inline-flex min-h-[44px] min-w-[44px] items-center justify-center rounded-lg text-dark-text text-2xl hover:bg-primary/10 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary"
            onClick={toggleMobileMenu}
            aria-label={isMobileMenuOpen ? 'Close main navigation' : 'Open main navigation'}
            aria-controls="main-navigation"
            aria-expanded={isMobileMenuOpen}
          >
            <FiMenu />
          </button>
        </nav>
      </div>
    </header>
  );
};

export default Header;
